 if(row.match_kind==='approved_alternative')return `<b>${money(row.subtotal/100)}</b><small>${money(row.price/100)} × ${esc(purchaseLabel(row.purchase_quantity,row.purchase_label||(row.weighted?'יחידות מכירה':'אריזות')))}${row.manual_conversion?' · לפי הכמות שאישרתם':''}</small>`;
