function listModal(text='',options={}){
 openModal(`<div class="detail-eyebrow">${options.fromPhoto?'בדיקת מה שנקרא מהצילום':'הרשימה שלך'}</div><h2>נבדוק כל שורה לפני ההוספה</h2><p>מוצר בכל שורה. אפשר לציין כמות כך: חלב × 2. שורות בעייתיות מסומנות עם הסבר.</p><label for="bulkList">רשימת הקניות</label><textarea id="bulkList" placeholder="חלב 3% × 2&#10;קפה שחור&#10;אורז בסמטי">${esc(text)}</textarea><div id="listFeedback" aria-live="polite"></div><button id="resolveStart" class="primary wide">בדיקת המוצרים ברשימה ${icon('arrow')}</button><button id="continueValidLines" class="outline wide" hidden></button>${options.fromPhoto?'<button id="retryListPhoto" class="text-btn">צילום הרשימה מחדש</button><button id="switchToProductPhoto" class="text-btn">צילמת מוצר? מעבר לחיפוש מתמונה</button>':''}`);
 let edited=false;
 const inspect=()=>inspectList($('bulkList').value,edited?{}:options);
 const draw=()=>{const d=inspect();$('listFeedback').innerHTML=d.too_many?'<div class="notice error">יש יותר מ־200 שורות. פצלו את הרשימה לשתי קניות.</div>':d.issues.length?`<div class="recognition-feedback"><h3>${d.valid.length?`${d.valid.length===1?'שורה אחת מוכנה לחיפוש':d.valid.length+' שורות מוכנות לחיפוש'} · ${d.issues.length} לבדיקה`:(d.low_confidence?'הקריאה מהצילום צריכה בדיקה':'עדיין לא נקרא שם מוצר ברור')}</h3>${d.issues.slice(0,12).map(row=>`<div class="line-issue"><button class="text-btn" data-fix-line="${row.line}">שורה ${row.line}: <bdi>${esc(row.raw.slice(0,60))}</bdi></button><p>${esc(row.reason)}</p></div>`).join('')}${d.issues.length>12?`<p>ועוד ${d.issues.length-12} שורות לבדיקה.</p>`:''}</div>`:d.valid.length?`<p class="recognition-ok">${d.valid.length===1?'שורה אחת מוכנה לחיפוש':d.valid.length+' שורות מוכנות לחיפוש'}. בהמשך בוחרים את המוצרים המדויקים.</p>`:'';
 $('resolveStart').disabled=d.empty||d.too_many;$('continueValidLines').hidden=!d.valid.length||!d.issues.length||d.too_many;$('continueValidLines').textContent=d.valid.length===1?'להמשיך רק עם השורה התקינה':`להמשיך רק עם ${d.valid.length} השורות התקינות`;
 for(const button of $('listFeedback').querySelectorAll('[data-fix-line]'))button.onclick=()=>{const area=$('bulkList'),parts=area.value.split(/\n|;/),index=Number(button.dataset.fixLine)-1,start=parts.slice(0,index).reduce((n,s)=>n+s.length+1,0);area.focus();area.setSelectionRange(start,start+(parts[index]?.length||0));};};
 const proceed=onlyValid=>{const d=inspect();if(d.too_many||d.empty)return draw();if(d.issues.length&&!onlyValid){draw();$('listFeedback').scrollIntoView({block:'nearest'});return;}pending=d.valid.map(({query,quantity})=>({query,quantity}));write('pending',pending);resolveIndex=0;resolveModal();};
 $('bulkList').oninput=()=>{edited=true;draw()};$('resolveStart').onclick=()=>proceed(false);$('continueValidLines').onclick=()=>proceed(true);if($('retryListPhoto'))$('retryListPhoto').onclick=()=>choosePhoto('list');if($('switchToProductPhoto'))$('switchToProductPhoto').onclick=()=>choosePhoto('product');draw();if(!options.fromPhoto)$('bulkList').focus();
}
function resolveModal(){return batchList.open();}

function basketRequest(){return {city:$('city').value.trim(),store_ids:[...selectedStores],items:cart.map(requestItem),include_delivery:$('includeDelivery').checked,extra_stop_cost:0,compute_split:false,page_size:24};}
function updateBasketPrices(force=false){const scope=scopeKey(basketRequest());if(localState.scope!==scope&&products.length)refreshLocalPrices();if(selectedScope!==scope){selectedBasketStore=null;selectedScope=scope;write('basketStore',{scope,id:null});}liveBasket.update(basketRequest(),{force});}
function selectBasketStore(id){selectedBasketStore=id;selectedScope=scopeKey(basketRequest());write('basketStore',{id,scope:selectedScope});}
function cancelComparison(){liveBasket.cancel();}
function compare(){updateBasketPrices(true);}
function onBasketState(state){
 liveState=state;results=state.data;
 if(state.phase==='ready'&&selectedBasketStore&&!results.stores.some(s=>s.id===selectedBasketStore)){toast('הסניף שבחרתם לא נכלל בבדיקה הנוכחית. מוצגת ההמלצה הזמינה.');selectBasketStore(null);}
 renderBadge();renderLiveSummary();renderCatalogQuote();if(view==='basket')renderCart();completionUI.update();
 if(results)renderComparison(results);else $('comparison').innerHTML='';
 if(state.phase==='ready'){
  experience.observe(results);
  const best=results.stores.find(s=>s.id===results.best),fingerprint=JSON.stringify([results.items,results.best,best?.total,$('city').value]);
  if(fingerprint!==lastBasketEvent){lastBasketEvent=fingerprint;const event={at:new Date().toISOString(),items:cart.length,basket:structuredClone(cart),best:best?best.chain_name+' · '+best.branch_name:null,total:best?.total??null,saving:results.savings,city:$('city').value};if(eventSession(events[0],event))events[0]=event;else events.unshift(event);events=events.slice(0,40);write('events',events);}
 }
}
function renderLiveSummary(){
 const host=$('liveBasketSummary');if(!host)return;$('basketSettingsLabel').textContent=(selectedStores.length?selectedStores.length+' סניפים נבחרים':$('city').value.trim()||'בחירת אזור')+' · הגדרות קנייה';
 const store=chosenBasketStore(),best=results?.stores.find(s=>s.id===results.best),busy=liveState.phase==='loading';
 $('compareButton').disabled=busy||!cart.length;$('compareButton').innerHTML=busy?'<span class="loader"></span> מעדכנים מחירים…':'רענון מחירים';
 if(!cart.length&&!pending.length){host.innerHTML='';return;}
 if(busy){const p=liveState.progress||{},previous=recommendStore(liveState.previous,selectedBasketStore);host.innerHTML=`<section class="recommendation"><div class="guide-step">הסל מתעדכן אוטומטית</div><h2>בודקים את הסל המעודכן</h2>${previous?.total!==null&&previous?.total!==undefined?`<p class="previous-quote">הבדיקה הקודמת: <b>${money(previous.total/100)}</b> · ${esc(previous.chain_name)}<small>זה אינו מחיר הסל לאחר השינוי</small></p>`:''}<p>${p.total===undefined?'טוענים מחירים באזור שבחרתם':`נבדקו ${p.checked} מתוך ${p.total} סניפים`}</p><progress ${p.total?`value="${p.checked}" max="${p.total}"`:''} aria-label="בדיקת מחירי הסל"></progress></section>`;return;}
 if(liveState.phase==='error'){host.innerHTML=`<section class="recommendation"><div class="guide-step">הסל נשמר</div><h2>${liveState.errorProductId?'נשאר לדייק כמות של מוצר':'בדיקת המחירים לא הושלמה'}</h2><p>${esc(liveState.error)}</p><button class="primary wide" ${liveState.errorProductId?'data-open-completion':'data-retry-basket'}>${liveState.errorProductId?'לבחירת הכמות':'ניסיון נוסף'}</button></section>`;return;}
 const d=shoppingReadiness(results,cart,store,0),cheapest=d.cartReady&&store.id===results.best;
 const checked=results?`<p class="recommendation-meta">נבדקו ${results.checked_stores} סניפים${results.errors.length?` · ${results.errors.length} מחירונים לא נטענו`:''}</p>`:'';
 if(!d.cartReady){host.innerHTML=`<section class="recommendation needs-review"><div class="guide-step">בדרך למחיר מלא</div><h2>${d.count===1?'עוד מוצר אחד לבדיקה':`עוד ${d.count} מוצרים לבדיקה`}</h2><p>${store?`${d.priced} מתוך ${cart.length} המוצרים עם מחיר${store.stale?' במחירון ישן':''} ב־${esc(store.chain_name)}.`:'עדיין אין מחיר עדכני לכל הבחירות.'}${pending.length?` ${pending.length} שורות מהרשימה ממתינות לבחירת מוצר.`:''}</p><button class="primary wide" data-open-completion>בדיקת אפשרויות להשלמת הסל ←</button>${selectedBasketStore?'<button class="text-btn wide" data-auto-store>בחירת הסופר הזול אוטומטית</button>':''}${best&&store?.id!==best.id?`<button class="outline wide" data-basket-store="${esc(best.id)}">מעבר לסניף עם מחיר מלא</button>`:''}<details class="partial-price-details"><summary>מה כבר תומחר?</summary>${store?`<p>${store.matched_count} המוצרים המתומחרים בלבד: <b>${money(store.shelf_total/100)}</b>. ${cart.length-store.matched_count} מוצרים נוספים אינם כלולים בסכום${pending.length?', וגם השורות שעדיין לא נבחרו':''}.</p><button class="text-btn" data-basket-price-details="${esc(store.id)}">פירוט המוצרים והמחירים</button><p class="source-note">מחירון ${when(store.published_at)}</p>`:'<p>ממתינים לבחירת מוצרים או למחירונים באזור.</p>'}<button class="text-btn" data-open-basket-stores>כל הסניפים שנבדקו</button>${checked}</details></section>`;return;}
 host.innerHTML=`<section class="recommendation ready"><div class="guide-step">${selectedBasketStore?'הסל בסניף שבחרתם':cheapest?'הסל המלא הזול ביותר שנמצא':'מחיר הסל'}</div><strong class="recommendation-total">${money(store.total/100)}</strong><h2>${esc(store.chain_name)}</h2><p class="recommendation-branch">${esc(store.branch_name)}</p><div class="recommendation-coverage">✓ ${cart.length===1?'מחיר למוצר שבסל':'מחיר לכל '+cart.length+' המוצרים'}</div><p class="recommendation-meta">מחירון הסניף: ${when(store.published_at)}</p><div class="basket-result-actions"><button class="outline" data-open-basket-stores>סופרים נוספים${results.complete_count>1?' · '+results.complete_count:''}</button><button class="text-btn" data-start-shopping>למצב קניות ←</button></div>${selectedBasketStore?`<button class="text-btn wide" data-auto-store>בחירת הסופר הזול אוטומטית${best&&best.total<store.total?' · חיסכון '+money((store.total-best.total)/100):''}</button>`:''}</section>`;
}

function refreshLocalPrices(extra=[]){const list=[...new Map([...products,...extra].map(p=>[p.id,p])).values()];if(list.length)localPrices.update({...basketRequest(),items:list.slice(-200).map(p=>({id:p.id,quantity:1})),extra_stop_cost:0});}
function renderCatalogQuote(){
 const store=chosenBasketStore(),local=localState.scope===scopeKey(basketRequest())?localState:{phase:'loading',prices:new Map()};
 for(const element of document.querySelectorAll('[data-catalog-price]')){
  const product=products.find(p=>p.id===element.dataset.catalogPrice)||quickAdd.items().find(p=>p.id===element.dataset.catalogPrice),row=store?.products.find(p=>p.id===element.dataset.catalogPrice),price=local.prices.get(element.dataset.catalogPrice);
  if(!product)continue;
  element.innerHTML=row&&!row.missing&&!store.stale&&(!row.matched_id||row.matched_id===product.id)?`<small>${esc(store.chain_name)} · בסניף הסל</small>${money(row.price/100)}`:price?`<small>החל מ־ · באזור שבחרתם</small>${money(price.price/100)}<small class="local-price-note">${esc(price.chain)} · ${when(price.published_at)}</small>`:local.phase==='loading'?'<small>בודקים מחיר באזור…</small>—':local.phase==='error'?'<small>המחיר המקומי לא נטען</small><small>לחצו לבדיקת סניפים</small>':'<small>אין מחיר עדכני באזור</small><small>לחצו לבחירת אזור אחר</small>';
 }
}
function basketStoresModal(){basketPricesUI.stores();}
function travelComparison(d){
 if(!$('splitEnabled').checked)return '';
 const extra=Math.round(Number($('stopCost').value)*100);if(!Number.isFinite(extra)||extra<0||extra>100000)return '';const split=summarize(d.stores,d.items,extra).split,best=d.stores.find(s=>s.id===d.best);
 if(!split)return '<p class="source-note">נבדקה גם קנייה בשתי חנויות: לא נמצא יתרון לאחר תוספת הזמן והדלק שבחרתם.</p>';
 const total=split.subtotal+extra,saving=best?best.total-total:null;
 return `<details class="split-box split-suggestion"><summary>${saving===null?'אפשר להשלים את הסל בשני סניפים':'אפשר לחסוך '+money(saving/100)+' בשני סניפים'} ←</summary><div class="result-eyebrow">כולל תוספת הזמן והדלק שבחרתם</div><h3>${saving===null?'שתי חנויות משלימות את הסל':saving>0?'אחרי העצירה הנוספת נשאר חיסכון של '+money(saving/100):'לפי העלות שבחרת, עדיף לקנות בחנות אחת'}</h3><p>${split.stores.map(s=>esc(s.name)).join(' + ')}</p><div class="cost-breakdown">${best?`<div><span>סל מלא בחנות אחת</span><b>${money(best.total/100)}</b></div>`:''}<div><span>המוצרים בשתי החנויות</span><b>${money(split.subtotal/100)}</b></div><div><span>תוספת זמן ודלק שבחרת</span><b>+ ${money(extra/100)}</b></div><div class="cost-total"><span>שתי חנויות, כולל התוספת</span><b>${money(total/100)}</b></div>${saving!==null?`<div class="${saving>0?'cost-saving':''}"><span>${saving>0?'החיסכון שנשאר':saving===0?'אין חיסכון לאחר התוספת':'יקר יותר מחנות אחת ב־'}</span><b>${money(Math.abs(saving)/100)}</b></div>`:''}</div><p class="source-note">התוספת היא ההערכה שלך לעצירה השנייה. אין כאן חישוב מרחק או מסלול; הנסיעה לחנות הראשונה אינה נכללת.</p><details><summary>מה לקנות בכל חנות?</summary>${split.stores.map(s=>`<h4>${esc(s.name)}</h4>${split.assignments.filter(a=>a.store_id===s.id).map(a=>`<p>${esc(productName(a.id))}${a.matched_name?' — '+esc(a.matched_name):''} × ${a.purchase_quantity??a.quantity}${a.purchase_label?' '+esc(a.purchase_label):''} · ${money(a.subtotal/100)}</p>`).join('')}`).join('')}</details></details>`;
}
function orderModal(chain=''){
 if(!cart.length)return toast('מוסיפים מוצרים לסל לפני מעבר לקנייה');
 const orderItems=purchaseItems(cart,chosenBasketStore()),chosen=retailers.find(r=>r.id===chain),list=chosen?[chosen,...retailers.filter(r=>r!==chosen)]:retailers;
 openModal(`<div class="detail-eyebrow">ממשיכים לקנייה</div><h2>מעתיקים רשימה, פותחים את הרשת</h2>${chain&&!chosen?`<p class="notice">אין כאן קישור הזמנה מאומת ל־${esc(chosenBasketStore()?.chain_name||chain)}. אפשר להעתיק את הרשימה או לבחור אתר אחר מהרשימה למטה.</p>`:''}<p>כאן מכינים רשימה; את ההזמנה והתשלום משלימים באתר הרשת. הרשימה אינה עוברת לעגלה באופן אוטומטי.</p><div class="order-steps"><b>1. מעתיקים את הרשימה</b><button id="copyOrderList" class="outline wide">${cart.length===1?'העתקת המוצר והכמות':`העתקת ${cart.length} מוצרים וכמויות`}</button><details><summary>הצגת הרשימה</summary><textarea id="orderList" readonly aria-label="רשימת הקניות להזמנה">${esc(shoppingList(orderItems))}</textarea></details><b>2. בוחרים אתר להזמנה</b>${list.map(r=>`<a class="retailer-link" href="${r.url}" target="_blank" rel="noopener noreferrer"><span class="chain-avatar">${esc(r.name.slice(0,2))}</span><span><b>${esc(r.name)}</b><small>פתיחת אתר ההזמנות</small></span><span aria-hidden="true">↗</span></a>`).join('')}</div><p class="notice">מחירי האונליין, המלאי, דמי המשלוח ואזורי החלוקה נקבעים באתר הרשת. הם עשויים להיות שונים ממחירי הסניף שבהשוואה.</p>`);
 $('copyOrderList').onclick=async()=>{try{await navigator.clipboard.writeText(shoppingList(orderItems));$('copyOrderList').textContent='הרשימה הועתקה ✓'}catch{$('orderList').closest('details').open=true;$('orderList').focus();$('orderList').select();toast('אפשר להעתיק את הרשימה מהשדה שנפתח')}};
}

const productName=id=>cart.find(p=>p.id===id)?.name||id;
function renderComparison(d){$('comparison').innerHTML=travelComparison(d)+'<p class="comparison-note">מחירי מדף לפי המוצרים, הסוגים והכמויות שבחרתם, ללא חישוב מבצעים ודמי משלוח. מחירון אינו אישור למלאי. הסכום מתעדכן אוטומטית; אפשר לבדוק כל מוצר בלחיצה.</p>'; }

function saveModal(){if(!cart.length)return toast('הסל ריק');openModal('<h2>נותנים לסל מקום קבוע</h2><label for="basketName">שם הסל</label><input id="basketName" class="field-input" maxlength="60" placeholder="למשל: הקנייה השבועית"><button id="confirmSave" class="primary wide">שמירה במכשיר</button>');$('basketName').focus();$('confirmSave').onclick=()=>{const name=$('basketName').value.trim()||'הסל שלי';saved.unshift({id:(crypto.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2)),name,items:structuredClone(cart),at:new Date().toISOString()});saved=saved.slice(0,30);write('saved',saved);closeModal();toast('הסל נשמר · '+name)}}
function renderSaved(){$('savedList').innerHTML=saved.length?saved.map(s=>`<article class="saved-card">${icon('heart')}<h3>${esc(s.name)}</h3><p>${countLabel(s.items.length,'מוצר','מוצרים')} · ${when(s.at)}<br>${s.items.slice(0,3).map(p=>esc(p.name)).join('، ')}</p><div class="row"><button class="primary" data-load="${esc(s.id)}">פתיחת הסל</button><button class="text-btn danger" data-delete-saved="${esc(s.id)}">מחיקה</button></div></article>`).join(''):empty('הסל הבא כבר יהיה קל יותר','שומרים סל מתוך מסך הסל, ופותחים אותו שוב בקנייה הבאה.','heart')}
function renderActivity(){experience.renderWatch();const valid=events.filter(e=>e.total!==null);$('activityStats').innerHTML=[['השוואות שביצעת',events.length],['סלים שמורים',saved.length],['יעדי מחיר',alerts.length],['סלים מלאים שנמצאו',valid.length]].map(([label,v])=>`<div class="stat"><b>${num(v)}</b><span>${label}</span></div>`).join('');const earned=[['הצעד הראשון','ביצעת השוואת סל',events.length>0],['שגרה חכמה','שמרת סל לקנייה חוזרת',saved.length>0],['סל רציני','השווית לפחות 10 מוצרים',events.some(e=>e.items>=10)]];$('achievements').innerHTML=earned.map(([name,desc,done])=>`<div class="achievement ${done?'earned':''}">${icon(done?'check':'bag')}<b>${name}</b><p>${desc} · ${done?'הושג':'עדיין לא הושג'}</p></div>`).join('');$('historyList').innerHTML=events.length?events.slice(0,15).map(e=>`<div class="event-row"><div><b>${esc(e.best||'לא נמצא סל מלא')}</b><p>${countLabel(e.items,'מוצר','מוצרים')} · ${esc(e.city)} · ${when(e.at)}</p></div><b>${e.total===null?'—':money(e.total/100)}</b></div>`).join(''):empty('עוד אין השוואות','ההיסטוריה תופיע כאן אחרי ההשוואה הראשונה.','chart');$('alertList').innerHTML=alerts.length?alerts.map(a=>`<div class="event-row"><div><b>${esc(a.name)}</b><p>יעד: ${money(a.target)} · ${esc(a.store_name)}${a.last_price!==undefined?' · נבדק: '+money(a.last_price):''}${a.reached?' · המחיר הגיע ליעד ✓':''}</p></div><button class="delete" data-delete-alert="${esc(a.id)}" aria-label="מחיקת התראה">×</button></div>`).join(''):'<p class="muted">פותחים פרטי מוצר ובוחרים יעד מחיר בסניף.</p>'}
async function loadStatus(){try{status=await api('status');$('connection').textContent=`${num(status.priced_stores)} סניפים עם מחירונים${status.collector?.refresh_overdue?' · עדכון מתעכב':''}`;$('cities').innerHTML=[...new Set(status.stores.filter(s=>s.has_prices&&s.city&&!/^\d+$/.test(s.city)).map(s=>s.city))].sort((a,b)=>a.localeCompare(b,'he')).map(c=>`<option value="${esc(c)}">`).join('');if(view==='coverage')renderCoverage();return status;}catch(e){$('connection').textContent='הכיסוי לא נטען';if(view==='coverage')$('coverageNotice').textContent=e.message;}}
function collectionMessage(c){if(!c)return '';const messages={running:'איסוף מתבצע כעת.',finished:'האיסוף האחרון הסתיים.',time_budget:'האיסוף הסתיים בתקציב הזמן; המחירונים שנקלטו פורסמו.',failed:'האיסוף האחרון נכשל; נשמרו המחירונים התקינים.',interrupted:'הריצה האחרונה לא דיווחה על סיום.',unknown:'אין דיווח סיום לריצה האחרונה.'};return (messages[c.status]||messages.unknown)+(c.refresh_overdue?' העדכון הבא מתעכב.':'')}
function renderCoverage(){if(!status){$('coverageNotice').textContent='טוענים את דוח הכיסוי…';loadStatus();return}$('coverageStats').innerHTML=[['רשתות עם מחירים',`${status.priced_chains}/${status.registered_chains}`],['סניפים עם מחירים',num(status.priced_stores)],['מוצרים שונים',num(status.products)],['רשומות מחיר',num(status.price_records)]].map(([label,v])=>`<div class="stat"><b>${v}</b><span>${label}</span></div>`).join('');$('coverageNotice').textContent=`${collectionMessage(status.collector)} דוח איסוף: ${when(status.generated_at)}. אותרו ${num(status.discovered_stores)} סניפים; ל־${num(status.priced_stores)} מהם נקלט מחירון. ${num(status.fresh_stores)} מחירונים בני עד 36 שעות. האיסוף מתוזמן כל ${status.schedule_hours} שעות; זמני המקור מוצגים בנפרד.${status.refresh_error?' רענון הדוח נכשל; מוצג הדוח האחרון.':''}`;$('chainList').innerHTML=status.chains.map(c=>`<details><summary class="chain-row"><div><b>${esc(c.name)}</b><p>${num(c.priced)} סניפים עם מחירון · ${num(c.discovered)} ברשימת הסניפים הרשמית</p></div><span class="chain-status">${c.status==='ok'?'הקליטה הושלמה':c.priced?'כיסוי חלקי':'ללא מחירים מאומתים'}</span></summary><div class="chain-details"><a href="${esc(c.portal)}" target="_blank" rel="noopener">פורטל שקיפות המחירים הרשמי ↗</a><br>נבדק: ${when(c.checked_at)}${(c.errors||[]).map(e=>'<p dir="auto">'+esc(e)+'</p>').join('')}${status.stores.filter(s=>s.chain===c.id&&s.error).slice(0,15).map(s=>`<p>${esc(s.name)}: ${esc(s.error)}</p>`).join('')}</div></details>`).join('')}
async function branchesModal(){if(!status){openModal('<div class="loading-block"><span class="loader"></span>טוענים את הסניפים…</div>');const token=modalToken;await loadStatus();if(token!==modalToken||!$('dialog').open)return;if(!status){openModal(empty('רשימת הסניפים לא נטענה','בדקו את החיבור ונסו שוב.'));return;}}openModal('<h2>הסניפים שנכנסים להשוואה</h2><p>בהשוואה לפי עיר נבדקים כל הסניפים בעיר. אפשר גם לצמצם ידנית לעד 60 סניפים מסוימים.</p><label for="branchSearch">עיר, רשת, שם או כתובת</label><input id="branchSearch" class="field-input" placeholder="למשל חיפה או רמי לוי"><div class="branch-quick"><button id="selectVisibleBranches" class="outline">בחירת התוצאות (עד 60)</button><button id="clearBranchSelection" class="outline">ניקוי הבחירה</button></div><div id="branchOptions" class="branch-list"></div><div class="dialog-actions"><button id="resetBranches" class="outline">חזרה להשוואה לפי עיר</button><button id="applyBranches" class="primary">אישור בחירה</button></div>');let selection=new Set(selectedStores);const draw=()=>{const q=$('branchSearch').value.trim(),exactCity=status.stores.some(s=>s.city===q);$('branchOptions').innerHTML=status.stores.filter(s=>s.has_prices&&(!q||(exactCity?s.city===q:(s.chain_name+' '+s.name+' '+s.city+' '+s.address).includes(q)))).slice(0,150).map(s=>`<label class="branch-select"><input type="checkbox" data-store="${esc(s.id)}" ${selection.has(s.id)?'checked':''}><span>${esc(s.chain_name+' · '+s.name)}<small>${esc(s.city+' · '+s.address)} · ${when(s.published_at)}${s.stale?' · מחירון ישן':''}</small></span></label>`).join('');};$('branchSearch').value=$('city').value;draw();$('branchSearch').oninput=draw;$('selectVisibleBranches').onclick=()=>{selection=new Set([...$('branchOptions').querySelectorAll('[data-store]')].slice(0,60).map(e=>e.dataset.store));draw();toast(`${selection.size} סניפים נבחרו. לחצו אישור לשמירה.`)};$('clearBranchSelection').onclick=()=>{selection.clear();draw()};$('branchOptions').onchange=e=>{if(!e.target.dataset.store)return;if(e.target.checked){if(selection.size>=60){e.target.checked=false;return toast('עד 60 סניפים להשוואה')}selection.add(e.target.dataset.store)}else selection.delete(e.target.dataset.store)};$('resetBranches').onclick=()=>{cancelComparison();selectedStores=[];write('stores',[]);$('branchesButton').querySelector('span').textContent='סניפים';closeModal();updateBasketPrices();toast('ההשוואה תיעשה לפי העיר')};$('applyBranches').onclick=()=>{cancelComparison();selectedStores=[...selection];write('stores',selectedStores);$('branchesButton').querySelector('span').textContent=selectedStores.length?`${selectedStores.length} סניפים`:'סניפים';closeModal();updateBasketPrices();toast('בחירת הסניפים נשמרה')};}
function ownerName(p){const info=identity(p);return p.identity?.chain_name||status?.stores?.find(s=>s.chain===info.chain)?.chain_name||({'shufersal':'שופרסל','rami-levy':'רמי לוי','tiv-taam':'טיב טעם','fresh-market':'פרש מרקט','osher-ad':'אושר עד','yochananof':'יוחננוף'}[info.chain])||info.chain;}
