  $('dialogBody').innerHTML=`<div class="detail-product">${p?productArt(p):''}<div><div class="detail-eyebrow">${parseNeed(d.id)?'הסוג שבחרתם. המחירים ברשתות.':p&&identity(p).chain?'מחירי המוצר בתוך הרשת':'אותו מוצר. המחירים בסניפים.'}</div><h2>${esc(p?.name||'טוענים מוצר…')}</h2>${parseNeed(d.id)?'<p>התאמה לפי סוג ותיאור · מחיר לק״ג</p>':p?`<p>${identity(p).chain?`קוד מוצר של ${esc(ownerName(p))}`:'ברקוד'} <span dir="ltr">${esc(identity(p).code)}</span>${p.weighted?' · מחיר לק״ג':''}</p>`:''}</div></div>${p&&/^\d{14}$/.test(p.id)?`<details class="image-provenance"><summary>אודות תמונת המוצר</summary><p>תמונות מ־Open Food Facts לפי הברקוד. כשאין תמונה זמינה מוצג איור מסומן.<br><a href="https://world.openfoodfacts.org/product/${/^0{6}\d{8}$/.test(p.id)?p.id.slice(6):p.id.replace(/^0/,'')}" target="_blank" rel="noopener noreferrer">צפייה במקור או הוספת צילום משלך ↗</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener noreferrer">רישיון CC BY-SA</a></p></details>`:''}${p?needControls(p,d.quantity):''}${d.replaceFrom?`<p class="need-replacement">לאחר האישור, הבחירה תחליף בסל את ״${esc(cart.find(x=>x.id===d.replaceFrom)?.name||'הפריט הקודם')}״. המותג וארץ המקור יכולים להיות שונים.</p>`:''}<div class="price-context">${icon('pin')}<label for="productScope" class="sr-only">אזור להשוואת המוצר</label><select id="productScope">${selectedStores.length?`<option value="selected">הסניפים שבחרתי</option>`:''}${$('city').value.trim()?`<option value="city">${esc($('city').value.trim())}</option>`:''}<option value="all">כל הארץ</option></select><label for="productChain" class="sr-only">סינון רשת</label><select id="productChain" class="chain-filter"><option value="">${p&&identity(p).chain?'סניפי '+esc(ownerName(p)):'כל הרשתות'}</option>${[...new Map(scopeBranches().map(s=>[s.chain,s.chain_name])).entries()].sort((a,b)=>a[1].localeCompare(b[1],'he')).map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('')}</select></div>${p&&identity(p).chain?`<div class="identity-notice"><b>למה רואים כאן רק ${esc(ownerName(p))}?</b><p>${p.weighted?'זה מוצר במשקל, שמזוהה אצלנו בקוד של הרשת.':'זה פריט שמזוהה אצלנו בקוד של הרשת.'} ברשת אחרת יכול להופיע מוצר דומה בקוד אחר; אין כאן התאמה מאומתת ביניהם.</p><button id="findAlternatives" class="outline wide">חיפוש חלופות ברשתות אחרות ←</button></div>`:''}${p&&!parseNeed(p.id)?`<button id="configureAlternatives" class="universal-alternatives"><b>גמישים במותג או באריזה? ←</b><small>בחירת חלופות למוצר הזה וחישוב הסל איתן בכל הרשתות</small></button>`:''}${p?typeOffer(p,cart.some(x=>x.id===p.id)):''}<div id="priceResults" aria-live="polite"></div><p class="modal-help">מחירי מדף מקובצי הרשתות, ללא דמי משלוח. מבצעים אינם מחושבים כאן. מחירון אינו אישור למלאי בסניף.</p><div class="detail-footer"><button id="detailAdd" class="primary wide" ${p?'':'disabled'}>${d.replaceFrom?'אישור והחלפת הפריט בסל':parseNeed(d.id)?'＋ הוספת הסוג לסל':'＋ הוספה לסל'}</button></div>`;
  $('productScope').value=d.scope;$('productChain').value=d.chain;
  $('productScope').onchange=()=>{d.scope=$('productScope').value;d.chain='';resetPriceScope();};
