  for(const select of document.querySelectorAll('[data-need-setting]'))select.onchange=()=>{const spec={...parseNeed(d.id),[select.dataset.needSetting]:select.value};d.id=needId(spec);d.product=needProduct(d.id);resetPriceScope();};
