  $('detailAdd').onclick=()=>{if(!d.product)return;const quantity=parseNeed(d.id)?d.quantity:1;if(!Number.isFinite(quantity)||quantity<.001||quantity>99)return toast('בחרו משקל בין 0.001 ל־99 ק״ג');if(d.replaceFrom){const target=cart.find(x=>x.id===d.id&&x.id!==d.replaceFrom);if((target?.quantity||0)+quantity>99)return toast('הכמות הכוללת לסוג הזה חורגת מ־99 ק״ג');cart=cart.filter(x=>x.id!==d.replaceFrom);}if(add(d.product,quantity)){d.replaceFrom=null;closeModal();navigate('basket');}};
